package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.EditText;import org.json.*;import java.util.*;
final class StudyInk extends View {
 static class Stroke{int color;float width,bw=0,bh=0;ArrayList<PointF> points=new ArrayList<>();Stroke(int c,float w){color=c;width=w;}}
 static class Model{ArrayList<Stroke> strokes=new ArrayList<>();Stroke active;int points=0;boolean begin(float x,float y,int c,float w){if(points>=12000||strokes.size()>=400)return false;active=new Stroke(c,w);strokes.add(active);add(x,y);return true;}void add(float x,float y){if(active==null||points>=12000)return;active.points.add(new PointF(Math.max(0,Math.min(1,x)),Math.max(0,Math.min(1,y))));points++;}void end(){active=null;}void cancel(){if(active!=null){points-=active.points.size();strokes.remove(active);active=null;}}void undo(){end();if(!strokes.isEmpty())points-=strokes.remove(strokes.size()-1).points.size();}void clear(){strokes.clear();active=null;points=0;}
 String json(){JSONArray a=new JSONArray();try{for(Stroke s:strokes){JSONArray points=new JSONArray();for(PointF point:s.points){points.put(Math.round(point.x*1000));points.put(Math.round(point.y*1000));}a.put(new JSONObject().put("c",s.color).put("w",s.width).put("bw",s.bw).put("bh",s.bh).put("p",points));}}catch(Exception e){throw new IllegalStateException(e);}return a.toString();}
 static Model parse(String value)throws Exception{if(value.length()>300000)throw new Exception("Ink data too large");Model model=new Model();JSONArray a=new JSONArray(value);if(a.length()>400)throw new Exception("Too many strokes");for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);float width=(float)o.getDouble("w");if(width<1||width>60||Float.isNaN(width))throw new Exception("Invalid pen width");Stroke stroke=new Stroke(o.getInt("c"),width);stroke.bw=(float)o.optDouble("bw",0);stroke.bh=(float)o.optDouble("bh",0);if(Float.isNaN(stroke.bw)||Float.isNaN(stroke.bh)||stroke.bw<0||stroke.bh<0||stroke.bw>100000||stroke.bh>10000000)throw new Exception("Invalid ink dimensions");JSONArray points=o.getJSONArray("p");if(points.length()%2!=0||points.length()<2)throw new Exception("Invalid stroke");for(int n=0;n<points.length();n+=2){int x=points.getInt(n),y=points.getInt(n+1);if(x<0||y<0||x>1000||y>1000||++model.points>12000)throw new Exception("Invalid ink points");stroke.points.add(new PointF(x/1000f,y/1000f));}model.strokes.add(stroke);}return model;}
 void draw(Canvas canvas,RectF box){canvas.save();canvas.clipRect(box);Paint pen=new Paint(3);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);for(Stroke stroke:strokes){float height=stroke.bw>0&&stroke.bh>0?stroke.bh*box.width()/stroke.bw:box.height();pen.setColor(stroke.color);pen.setStrokeWidth(stroke.width*box.width()/1000f);if(stroke.points.size()==1){PointF point=stroke.points.get(0);pen.setStyle(Paint.Style.FILL);canvas.drawCircle(box.left+point.x*box.width(),box.top+point.y*height,pen.getStrokeWidth()/2,pen);}else{Path path=new Path();boolean first=true;for(PointF point:stroke.points){float x=box.left+point.x*box.width(),y=box.top+point.y*height;if(first){path.moveTo(x,y);first=false;}else path.lineTo(x,y);}pen.setStyle(Paint.Style.STROKE);canvas.drawPath(path,pen);}}canvas.restore();}}
 final Model model;final Runnable changed;boolean writing=false;int color=0xff245cb3;float width=4,lastY=0;EditText anchor;ViewTreeObserver observer;final ViewTreeObserver.OnScrollChangedListener scrollListener=()->invalidate();
 StudyInk(Context context,Model value,Runnable callback){super(context);model=value;changed=callback;setContentDescription("Saved school handwriting layer. Type passes touches to typed notes; Ink draws over them. Two fingers scroll in Ink mode.");}
 void unobserve(){if(observer!=null&&observer.isAlive())observer.removeOnScrollChangedListener(scrollListener);observer=null;}
 void observe(){unobserve();if(anchor!=null&&getWindowToken()!=null){observer=anchor.getViewTreeObserver();observer.addOnScrollChangedListener(scrollListener);}}
 void bind(EditText editor){anchor=editor;observe();invalidate();}
 protected void onAttachedToWindow(){super.onAttachedToWindow();observe();}
 protected void onDetachedFromWindow(){unobserve();super.onDetachedFromWindow();}
 float documentHeight(){return anchor==null?Math.max(1,getHeight()):Math.max(getHeight(),anchor.getLayout()==null?getHeight():anchor.getLayout().getHeight()+anchor.getCompoundPaddingTop()+anchor.getCompoundPaddingBottom());}
 float documentY(float y){return y+(anchor==null?0:anchor.getScrollY());}
 protected void onDraw(Canvas canvas){if(anchor==null){canvas.drawColor(Color.WHITE);Paint line=new Paint();line.setColor(0xffdce7f1);for(int y=24;y<getHeight();y+=28)canvas.drawLine(0,y,getWidth(),y,line);}canvas.save();if(anchor!=null)canvas.translate(0,-anchor.getScrollY());model.draw(canvas,new RectF(0,0,getWidth(),documentHeight()));canvas.restore();}
 public boolean onTouchEvent(MotionEvent event){if(!writing||getWidth()==0||getHeight()==0)return false;int action=event.getActionMasked();if(event.getPointerCount()>1){model.cancel();if(anchor!=null&&action==MotionEvent.ACTION_MOVE)anchor.scrollBy(0,Math.round(lastY-event.getY()));lastY=event.getY();invalidate();return true;}if(action==MotionEvent.ACTION_DOWN){lastY=event.getY();getParent().requestDisallowInterceptTouchEvent(true);if(model.begin(event.getX()/getWidth(),documentY(event.getY())/documentHeight(),color,width)){if(anchor!=null){model.active.bw=getWidth();model.active.bh=documentHeight();}}else android.widget.Toast.makeText(getContext(),"Ink limit reached; undo or use another page",1).show();}else if(action==MotionEvent.ACTION_MOVE){float height=model.active!=null&&model.active.bh>0?model.active.bh:documentHeight();for(int i=0;i<event.getHistorySize();i++)model.add(event.getHistoricalX(i)/getWidth(),documentY(event.getHistoricalY(i))/height);model.add(event.getX()/getWidth(),documentY(event.getY())/height);lastY=event.getY();}else if(action==MotionEvent.ACTION_UP){boolean edited=model.active!=null;model.end();if(edited)changed.run();getParent().requestDisallowInterceptTouchEvent(false);performClick();}else if(action==MotionEvent.ACTION_CANCEL){model.cancel();getParent().requestDisallowInterceptTouchEvent(false);}invalidate();return true;}public boolean performClick(){super.performClick();return true;}
}
